/* CSS PART 1 OF 2 */

/* ========================================
   DESIGN TOKENS
======================================== */
:root {
  --ink: #202a30;
  --ink-deep: #172126;
  --ink-soft: #46545a;
  --paper: #f6f5f1;
  --white: #ffffff;
  --muted: #e9e7e0;
  --line: #d8d7d0;
  --accent: #b66d43;
  --accent-dark: #92502f;
  --accent-light: #e7c4a9;

  --font-display: Georgia, "Times New Roman", serif;
  --font-body: "Helvetica Neue", Helvetica, Arial, sans-serif;

  --container: 1180px;
  --gutter: clamp(22px, 5vw, 76px);
  --section-space: clamp(76px, 10vw, 132px);

  --radius: 3px;
  --shadow: 0 18px 50px rgba(23, 33, 38, 0.12);

  --transition: 220ms ease;
}

/* ========================================
   RESET & GLOBAL
======================================== */
* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 4px;
}

::selection {
  background: var(--accent);
  color: var(--white);
}

/* ========================================
   SHARED TYPOGRAPHY
======================================== */
h1,
h2,
h3,
h4,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: -0.035em;
  line-height: 1.12;
}

h1 {
  font-size: clamp(3rem, 6.5vw, 6.2rem);
}

h2 {
  font-size: clamp(2.35rem, 4.5vw, 4rem);
}

h3 {
  font-size: clamp(1.55rem, 2.4vw, 2.15rem);
}

p {
  color: var(--ink-soft);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  color: var(--accent-dark);
  font-size: 0.72rem;
  font-weight: 750;
  letter-spacing: 0.17em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 27px;
  height: 2px;
  background: currentColor;
  content: "";
}

.section-heading {
  max-width: 760px;
  margin-bottom: 24px;
}

.section-intro {
  max-width: 650px;
  font-size: 1.08rem;
  line-height: 1.85;
}

.accent-text {
  color: var(--accent);
}

.text-light {
  color: rgba(255, 255, 255, 0.8);
}

/* ========================================
   PAGE LAYOUT
======================================== */
.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: var(--section-space);
}

.section--light {
  background: var(--white);
}

.section--dark {
  background: var(--ink-deep);
  color: var(--white);
}

.section--dark p {
  color: rgba(255, 255, 255, 0.72);
}

.section-header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: 52px;
}

.section-header > * {
  margin-bottom: 0;
}

/* ========================================
   HEADER & NAVIGATION
======================================== */
.site-header {
  position: relative;
  z-index: 20;
  background: var(--white);
  border-bottom: 1px solid rgba(32, 42, 48, 0.09);
}

.header-inner {
  display: flex;
  min-height: 94px;
  align-items: center;
  justify-content: space-between;
  gap: 36px;
}

.brand {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 14px;
}

.brand-logo {
  width: 66px;
  height: 66px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}

.brand-name {
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.22rem;
  font-weight: 700;
  letter-spacing: -0.035em;
}

.brand-description {
  margin-top: 5px;
  color: var(--ink-soft);
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(18px, 2.8vw, 38px);
}

.primary-nav a {
  position: relative;
  padding-block: 10px;
  color: var(--ink-soft);
  font-size: 0.81rem;
  font-weight: 650;
  transition: color var(--transition);
}

.primary-nav a::after {
  position: absolute;
  right: 0;
  bottom: 3px;
  left: 0;
  height: 2px;
  background: var(--accent);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.primary-nav a:hover {
  color: var(--accent-dark);
}

.primary-nav a:hover::after {
  transform: scaleX(1);
}

/* ========================================
   REUSABLE BUTTONS
======================================== */
.button {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 15px 25px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  cursor: pointer;
  font-size: 0.77rem;
  font-weight: 750;
  letter-spacing: 0.095em;
  line-height: 1.3;
  text-align: center;
  text-transform: uppercase;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  transform: translateY(-2px);
}

.button--primary {
  background: var(--accent);
  color: var(--white);
}

.button--primary:hover {
  background: var(--accent-dark);
}

.button--light {
  background: var(--white);
  color: var(--ink);
}

.button--light:hover {
  background: var(--muted);
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--white);
}

.button--outline:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--ink);
}

.button--dark-outline {
  border-color: var(--ink);
  background: transparent;
  color: var(--ink);
}

.button--dark-outline:hover {
  background: var(--ink);
  color: var(--white);
}

.button-arrow {
  font-size: 1.1rem;
  line-height: 1;
}

/* ========================================
   FULL-BLEED HERO
======================================== */
.hero {
  position: relative;
  display: flex;
  min-height: min(760px, calc(100svh - 94px));
  align-items: center;
  overflow: hidden;
  background-color: var(--ink-deep);
  background-image:
    linear-gradient(
      90deg,
      rgba(18, 28, 33, 0.91) 0%,
      rgba(18, 28, 33, 0.76) 43%,
      rgba(18, 28, 33, 0.24) 100%
    ),
    url("https://joshbrooksconstructionllc.com/wp-content/uploads/2026/09/finished-roof-ridge-thornton-co-768x1024.jpg");
  background-position: center, center 43%;
  background-repeat: no-repeat;
  background-size: cover;
  color: var(--white);
}

.hero::after {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 8px;
  background: var(--accent);
  content: "";
}

.hero-content {
  position: relative;
  z-index: 2;
  width: min(820px, 75%);
  padding-block: 110px 125px;
}

.hero .eyebrow {
  color: var(--accent-light);
}

.hero h1 {
  max-width: 850px;
  margin-bottom: 27px;
  color: var(--white);
}

.hero-description {
  max-width: 590px;
  margin-bottom: 36px;
  color: rgba(255, 255, 255, 0.84);
  font-size: clamp(1rem, 1.4vw, 1.16rem);
  line-height: 1.85;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 15px;
}

.hero-note {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 48px;
  color: rgba(255, 255, 255, 0.76);
  font-size: 0.76rem;
  font-weight: 650;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.hero-note::before {
  width: 35px;
  height: 1px;
  background: var(--accent-light);
  content: "";
}

/* ========================================
   INTRODUCTION / COMPANY POSITIONING
======================================== */
.intro-section {
  position: relative;
  padding-block: 100px;
  background: var(--paper);
}

.intro-layout {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: center;
  gap: 100px;
}

.intro-heading {
  max-width: 490px;
}

.intro-heading h2 {
  margin-bottom: 0;
}

.intro-copy {
  max-width: 570px;
}

.intro-copy p {
  margin-bottom: 20px;
  font-size: 1.04rem;
  line-height: 1.9;
}

.intro-emphasis {
  padding-left: 22px;
  border-left: 3px solid var(--accent);
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.4rem;
  line-height: 1.45;
}

/* ========================================
   SERVICES / OFFERINGS
======================================== */
.services-section {
  background: var(--white);
}

.services-layout {
  display: grid;
  grid-template-columns: 0.82fr 1.18fr;
  align-items: start;
  gap: 90px;
}

.services-heading {
  position: sticky;
  top: 35px;
}

.services-heading h2 {
  max-width: 440px;
}

.services-heading p {
  max-width: 400px;
}

.services-list {
  border-top: 1px solid var(--line);
}

.service-item {
  display: grid;
  grid-template-columns: 54px 1fr;
  gap: 22px;
  padding-block: 31px;
  border-bottom: 1px solid var(--line);
}

.service-number {
  padding-top: 5px;
  color: var(--accent);
  font-family: var(--font-display);
  font-size: 1.15rem;
}

.service-item h3 {
  margin-bottom: 10px;
}

.service-item p {
  max-width: 510px;
  margin-bottom: 0;
  font-size: 0.96rem;
}

/* ========================================
   WHY CHOOSE JOSH BROOKS
======================================== */
.why-section {
  position: relative;
  overflow: hidden;
  background: var(--ink-deep);
  color: var(--white);
}

.why-layout {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: center;
  gap: 90px;
}

.why-heading h2 {
  max-width: 500px;
  margin-bottom: 24px;
}

.why-heading .eyebrow {
  color: var(--accent-light);
}

.why-heading p {
  max-width: 450px;
}

.why-points {
  border-top: 1px solid rgba(255, 255, 255, 0.2);
}

.why-point {
  display: grid;
  grid-template-columns: 45px 1fr;
  gap: 22px;
  padding-block: 27px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
}

.why-point-number {
  color: var(--accent-light);
  font-family: var(--font-display);
  font-size: 1.2rem;
}

.why-point h3 {
  margin-bottom: 9px;
  color: var(--white);
  font-size: 1.55rem;
}

.why-point p {
  max-width: 480px;
  margin-bottom: 0;
  font-size: 0.94rem;
}

/* ========================================
   ROOF ATTENTION / EDUCATIONAL SECTION
======================================== */
.roof-section {
  background: var(--paper);
}

.roof-layout {
  display: grid;
  grid-template-columns: 1fr 0.85fr;
  align-items: center;
  gap: 90px;
}

.roof-content h2 {
  max-width: 620px;
}

.roof-content > p {
  max-width: 570px;
}

.roof-checklist {
  margin-top: 35px;
  padding: 0;
  border-top: 1px solid var(--line);
  list-style: none;
}

.roof-checklist li {
  position: relative;
  padding: 17px 10px 17px 29px;
  border-bottom: 1px solid var(--line);
  color: var(--ink-soft);
  font-size: 0.95rem;
}

.roof-checklist li::before {
  position: absolute;
  top: 25px;
  left: 2px;
  width: 9px;
  height: 9px;
  border: 2px solid var(--accent);
  border-radius: 50%;
  content: "";
}

.roof-image {
  position: relative;
  min-height: 510px;
  overflow: hidden;
  background: var(--muted);
}

.roof-image img {
  width: 100%;
  height: 100%;
  min-height: 510px;
  object-fit: cover;
  object-position: center;
}

.roof-image-caption {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 23px 26px;
  background: rgba(23, 33, 38, 0.88);
  color: var(--white);
  font-size: 0.76rem;
  font-weight: 650;
  letter-spacing: 0.06em;
}

/* ========================================
   COLORADO ROOFING PROCESS
======================================== */
.process-section {
  background: var(--white);
}

.process-heading {
  max-width: 700px;
  margin-bottom: 55px;
}

.process-heading h2 {
  max-width: 680px;
}

.process-layout {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.process-step {
  position: relative;
  padding: 37px 35px 42px 0;
}

.process-step + .process-step {
  padding-left: 35px;
  border-left: 1px solid var(--line);
}

.process-step-number {
  display: block;
  margin-bottom: 27px;
  color: var(--accent);
  font-family: var(--font-display);
  font-size: 2.5rem;
  line-height: 1;
}

.process-step h3 {
  margin-bottom: 15px;
  font-size: 1.65rem;
}

.process-step p {
  max-width: 320px;
  margin-bottom: 0;
  font-size: 0.94rem;
}

/* ========================================
   RECENT PROJECTS / PORTFOLIO
======================================== */
.projects-section {
  background: var(--paper);
}

.projects-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: 46px;
}

.projects-heading h2 {
  max-width: 620px;
  margin-bottom: 0;
}

.projects-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 30px;
}

.project-card {
  min-width: 0;
  background: var(--white);
}

.project-card--wide {
  grid-column: 1 / -1;
}

.project-image {
  position: relative;
  height: 380px;
  overflow: hidden;
  background: var(--muted);
}

.project-card--wide .project-image {
  height: 500px;
}

.project-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 500ms ease;
}

.project-card:hover .project-image img {
  transform: scale(1.035);
}

.project-details {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 24px 26px 27px;
}

.project-details h3 {
  margin-bottom: 7px;
  font-size: 1.55rem;
}

.project-details p {
  margin-bottom: 0;
  font-size: 0.83rem;
}

.project-category {
  flex-shrink: 0;
  padding: 7px 10px;
  background: var(--paper);
  color: var(--accent-dark);
  font-size: 0.65rem;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* ========================================
   GENERAL CONTENT LINKS
======================================== */
.text-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--accent-dark);
  font-size: 0.78rem;
  font-weight: 750;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  transition: gap var(--transition);
}

.text-link:hover {
  gap: 16px;
}

.text-link span {
  font-size: 1.1rem;
}

/* ========================================
   MOTION PREFERENCES
======================================== */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
