/* CSS PART 2 OF 2 */

/* ========================================
   CONTACT / CONVERSION SECTION
======================================== */
.contact-section {
  position: relative;
  overflow: hidden;
  background: var(--ink-deep);
  color: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: 90px;
}

.contact-copy {
  position: sticky;
  top: 40px;
}

.contact-copy .eyebrow {
  color: var(--accent-light);
}

.contact-copy h2 {
  max-width: 490px;
  margin-bottom: 24px;
  color: var(--white);
}

.contact-copy > p {
  max-width: 440px;
  color: rgba(255, 255, 255, 0.74);
}

.contact-detail {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  margin-top: 38px;
  padding-top: 25px;
  border-top: 1px solid rgba(255, 255, 255, 0.2);
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.9rem;
}

.contact-detail-mark {
  color: var(--accent-light);
  font-size: 1.15rem;
}

.contact-form {
  padding: clamp(26px, 4vw, 48px);
  background: var(--white);
  color: var(--ink);
  box-shadow: var(--shadow);
}

.form-heading {
  margin-bottom: 30px;
}

.form-heading h3 {
  margin-bottom: 9px;
  font-size: 1.9rem;
}

.form-heading p {
  margin-bottom: 0;
  font-size: 0.88rem;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 21px 18px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--ink);
  font-size: 0.76rem;
  font-weight: 750;
  letter-spacing: 0.055em;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-width: 0;
  min-height: 52px;
  padding: 13px 15px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: #faf9f6;
  color: var(--ink);
  font-size: 0.94rem;
  transition:
    border-color var(--transition),
    background var(--transition);
}

.form-field textarea {
  min-height: 135px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #747d80;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--accent);
  background: var(--white);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.form-submit {
  margin-top: 25px;
}

.form-submit .button {
  width: 100%;
}

.form-note {
  margin: 15px 0 0;
  color: #687277;
  font-size: 0.76rem;
  line-height: 1.6;
}

/* ========================================
   FOOTER
======================================== */
.site-footer {
  padding-top: 65px;
  background: #121b20;
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 60px;
  padding-bottom: 52px;
}

.footer-brand {
  max-width: 390px;
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-description {
  color: rgba(255, 255, 255, 0.62);
}

.footer-brand p {
  max-width: 350px;
  margin-top: 22px;
  color: rgba(255, 255, 255, 0.65);
  font-size: 0.88rem;
}

.footer-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 18px 35px;
  padding-top: 12px;
}

.footer-nav a {
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.79rem;
  font-weight: 650;
  transition: color var(--transition);
}

.footer-nav a:hover {
  color: var(--accent-light);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-block: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.16);
  color: rgba(255, 255, 255, 0.57);
  font-size: 0.73rem;
}

/* ========================================
   ACCESSIBLE MOBILE MENU BUTTON
======================================== */
.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--white);
  color: var(--ink);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* ========================================
   TABLET
======================================== */
@media (max-width: 1000px) {
  :root {
    --section-space: 86px;
  }

  .header-inner {
