/* ========================================
   MOBILE NAVIGATION & LAYOUT
======================================== */
@media (max-width: 760px) {
  :root {
    --gutter: 24px;
    --section-space: 74px;
  }

  html {
    scroll-padding-top: 75px;
  }

  .header-inner {
    position: relative;
    min-height: 76px;
    flex-wrap: wrap;
    gap: 0;
  }

  .brand {
    max-width: calc(100% - 62px);
    gap: 10px;
  }

  .brand-logo {
    width: 48px;
    height: 48px;
  }

  .brand-name {
    font-size: 1rem;
  }

  .brand-description {
    font-size: 0.53rem;
    letter-spacing: 0.08em;
  }

  .menu-toggle {
    display: inline-flex;
  }

  .primary-nav {
    position: absolute;
    top: 100%;
    right: calc(var(--gutter) * -1);
    left: calc(var(--gutter) * -1);
    display: none;
    align-items: stretch;
    flex-direction: column;
    gap: 0;
    padding: 10px var(--gutter) 20px;
    border-top: 1px solid var(--line);
    background: var(--white);
    box-shadow: 0 15px 25px rgba(23, 33, 38, 0.1);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a {
    display: block;
    width: 100%;
    padding: 14px 0;
    border-bottom: 1px solid var(--line);
    font-size: 0.86rem;
  }

  .primary-nav a::after {
    display: none;
  }

  .hero {
    min-height: 650px;
    min-height: min(760px, 88svh);
    background-image:
      linear-gradient(
        90deg,
        rgba(18, 28, 33, 0.84),
        rgba(18, 28, 33, 0.52)
      ),
      url("https://joshbrooksconstructionllc.com/wp-content/uploads/2026/09/finished-roof-ridge-thornton-co-768x1024.jpg");
    background-position: center, 57% center;
  }

  .hero-content {
    width: 100%;
    padding-block: 85px 95px;
  }

  .hero h1 {
    max-width: 620px;
    font-size: clamp(2.9rem, 10vw, 4.5rem);
  }

  .hero-description {
    max-width: 510px;
    font-size: 1rem;
  }

  .hero-note {
    margin-top: 35px;
    font-size: 0.68rem;
  }

  .section-header,
  .projects-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
    margin-bottom: 35px;
  }

  .intro-section {
    padding-block: 74px;
  }

  .intro-layout,
  .services-layout,
  .why-layout,
  .roof-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .intro-heading,
  .intro-copy {
    max-width: 100%;
  }

  .intro-emphasis {
    font-size: 1.25rem;
  }

  .services-heading {
    position: static;
  }

  .service-item {
    grid-template-columns: 38px 1fr;
    gap: 14px;
    padding-block: 24px;
  }

  .why-point {
    grid-template-columns: 35px 1fr;
    gap: 15px;
    padding-block: 23px;
  }

  .roof-image,
  .roof-image img {
    min-height: 350px;
    max-height: 470px;
  }

  .process-layout {
    grid-template-columns: 1fr;
  }

  .process-step,
  .process-step + .process-step {
    padding: 26px 0;
    border-left: 0;
    border-bottom: 1px solid var(--line);
  }

  .process-step:last-child {
    border-bottom: 0;
  }

  .process-step-number {
    margin-bottom: 17px;
