  }

  .project-details {
    padding: 20px;
  }

  .contact-copy {
    position: static;
  }

  .contact-layout {
    gap: 30px;
  }

  .contact-form {
    padding: 25px 21px;
  }

  .footer-main {
    flex-direction: column;
    gap: 30px;
  }

  .footer-nav {
    gap: 17px 24px;
  }
}

